import{_ as d,C as s,o as t,c as i,a2 as e,b as o,w as n,a as l,E as p,a3 as h}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Apple Theme for Pterodactyl (Admin)","description":"An iOS-grade matte glass admin theme for Pterodactyl Panel — Catppuccin Latte and Mocha, a runtime-harvested sidebar that adapts to every extension, bento dashboard and a branded boot loader, with zero core-file replacement.","frontmatter":{"title":"Apple Theme for Pterodactyl (Admin)","description":"An iOS-grade matte glass admin theme for Pterodactyl Panel — Catppuccin Latte and Mocha, a runtime-harvested sidebar that adapts to every extension, bento dashboard and a branded boot loader, with zero core-file replacement.","head":[["meta",{"name":"og:title","content":"Apple — iOS-Grade Admin Theme for Pterodactyl"}],["meta",{"name":"og:description","content":"A Blueprint theme that reskins the Pterodactyl admin area with matte glass, Catppuccin palettes and a sidebar that adapts to every installed extension automatically."}]]},"headers":[],"relativePath":"apple/index.md","filePath":"apple/index.md","lastUpdated":null}'),c={name:"apple/index.md"};function v(g,a,u,m,b,y){const r=s("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="apple-theme-for-pterodactyl-admin" tabindex="-1" data-v-3578108a>Apple Theme for Pterodactyl (Admin) <a class="header-anchor" href="#apple-theme-for-pterodactyl-admin" aria-label="Permalink to &quot;Apple Theme for Pterodactyl (Admin)&quot;" data-v-3578108a>​</a></h1><p data-v-3578108a><strong data-v-3578108a>An iOS-grade matte glass theme for the Pterodactyl admin area</strong>, built on the Blueprint framework. Apple replaces the stock AdminLTE chrome with a frosted sidebar and floating top bar, reskins every panel component in Catppuccin Mocha (dark) and Latte (light), and ships a custom bento dashboard — with <strong data-v-3578108a>zero core-file replacement</strong> and <strong data-v-3578108a>zero external assets</strong>.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-3578108a><p data-v-3578108a><strong data-v-3578108a>🍎 Built for PingLess Studios</strong><a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-3578108a>studio.pingless.org</a> · Single <code data-v-3578108a>.blueprint</code> package, standalone variant included</p></div><hr data-v-3578108a><h2 id="architecture" tabindex="-1" data-v-3578108a>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;" data-v-3578108a>​</a></h2>',5)),(t(),o(h,null,{default:n(()=>[p(r,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Panel%5B%22Pterodactyl%20Panel%22%5D%0A%20%20%20%20%20%20%20%20BP%5B%22Blueprint%20framework%22%5D%0A%20%20%20%20%20%20%20%20HUB%5B%22Apple%20hub%3Cbr%2F%3Econtroller.php%20%C2%B7%20view.blade.php%22%5D%0A%20%20%20%20%20%20%20%20DB%5B(%22Panel%20settings%20table%3Cbr%2F%3Eapple%3A%3A*%20keys%22)%5D%0A%20%20%20%20%20%20%20%20WRAP%5B%22admin%20wrapper%3Cbr%2F%3Erendered%20on%20every%20admin%20page%22%5D%0A%20%20%20%20%20%20%20%20VARS%5B%22variables.blade.php%3Cbr%2F%3Eserver-rendered%20CSS%20tokens%22%5D%0A%20%20%20%20%20%20%20%20HUB%20--%3E%20DB%0A%20%20%20%20%20%20%20%20WRAP%20--%3E%20VARS%0A%20%20%20%20%20%20%20%20DB%20--%3E%20WRAP%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Browser%5B%22Every%20admin%20page%20load%22%5D%0A%20%20%20%20%20%20%20%20LOADER%5B%22Boot%20loader%3Cbr%2F%3Ebranded%20splash%20%2B%20failsafe%22%5D%0A%20%20%20%20%20%20%20%20PRE%5B%22Pre-paint%20script%3Cbr%2F%3Emode%20%2B%20rail%20from%20localStorage%22%5D%0A%20%20%20%20%20%20%20%20CSS%5B%225%20CSS%20libraries%3Cbr%2F%3Ecore%20%C2%B7%20layout%20%C2%B7%20components%20%C2%B7%20dashboard%20%C2%B7%20mobile%22%5D%0A%20%20%20%20%20%20%20%20JS%5B%22sidebar.js%3Cbr%2F%3Eharvests%20stock%20nav%2C%20builds%20Apple%20chrome%22%5D%0A%20%20%20%20%20%20%20%20VARS%20--%3E%20PRE%0A%20%20%20%20%20%20%20%20PRE%20--%3E%20LOADER%0A%20%20%20%20%20%20%20%20LOADER%20--%3E%20CSS%0A%20%20%20%20%20%20%20%20LOADER%20--%3E%20JS%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Stock%5B%22Stock%20AdminLTE%20DOM%20(untouched)%22%5D%0A%20%20%20%20%20%20%20%20NAV%5B%22ul.sidebar-menu%3Cbr%2F%3Ecore%20%2B%20every%20extension's%20links%22%5D%0A%20%20%20%20%20%20%20%20JS%20-.-%3E%7C%22reads%20links%2C%20icons%2C%3Cbr%2F%3Eactive%20state%22%7C%20NAV%0A%20%20%20%20end%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e(`<p data-v-3578108a>Apple never edits a Pterodactyl core file to work. Blueprint renders Apple&#39;s wrapper at the end of every admin page; it emits server-rendered design tokens (so the first paint is already themed and in the right mode), then loads Apple&#39;s CSS and JS. The JavaScript <strong data-v-3578108a>harvests the panel&#39;s own sidebar menu at runtime</strong> — every link, icon and active state, including links injected by any other extension — and rebuilds it as the Apple navigation. Install another extension tomorrow and its pages simply appear.</p><hr data-v-3578108a><h2 id="key-features" tabindex="-1" data-v-3578108a>Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;" data-v-3578108a>​</a></h2><ul data-v-3578108a><li data-v-3578108a><strong data-v-3578108a>🌗 Catppuccin in both modes.</strong> Full Mocha (dark) and Latte (light) token sets, 12 official Catppuccin accents (blue, sapphire, sky, teal, green, yellow, peach, red, pink, mauve, lavender, flamingo), and a top-bar toggle that persists per browser. Admins pick the default: system, dark or light.</li><li data-v-3578108a><strong data-v-3578108a>🧊 Matte glass, not glassmorphism-for-show.</strong> Frosted sidebar, floating top bar and cards whose blur and opacity are settings (<code data-v-3578108a>0–30px</code> blur, <code data-v-3578108a>50–95%</code> opacity). Surfaces stay neutral — only the accent carries color, and on the sidebar only the icon does.</li><li data-v-3578108a><strong data-v-3578108a>🧭 A sidebar that adapts to everything.</strong> Section headers, links, icons and active states are read from the panel&#39;s own menu DOM, so any extension that registers an admin link — now or later — shows up automatically. Filter field, icon-rail collapse (persisted), and an off-canvas drawer with blurred backdrop on mobile.</li><li data-v-3578108a><strong data-v-3578108a>🍱 Bento dashboard.</strong> Greeting with real update status, live counts (servers, users, nodes, locations), a 14-day signup sparkline rendered as inline SVG (no chart CDN), quick actions, and a system tile. Toggleable — the stock dashboard ships inside the same file as a runtime fallback.</li><li data-v-3578108a><strong data-v-3578108a>🚀 Branded boot loader.</strong> A splash with your panel name, the Apple glyph and an accent progress ring while the chrome builds — with a CSS-only failsafe and a static reduced-motion variant.</li><li data-v-3578108a><strong data-v-3578108a>🧩 Every component reskinned globally.</strong> Boxes, buttons, forms, tables, tabs (as iOS segmented controls), alerts, callouts, modals, labels, pagination, dropdowns, select2, SweetAlert, stat widgets — extension pages look native without a line of per-extension work.</li><li data-v-3578108a><strong data-v-3578108a>♿ Accessibility as a contract.</strong> Body text ≥ 4.5:1 in both modes, visible focus rings, <code data-v-3578108a>prefers-reduced-motion</code> honored everywhere, status never carried by color alone.</li><li data-v-3578108a><strong data-v-3578108a>📦 Blueprint + standalone.</strong> One codebase ships as a <code data-v-3578108a>.blueprint</code> package (with settings hub) and as a standalone variant for panels without Blueprint.</li></ul><hr data-v-3578108a><h2 id="quick-install" tabindex="-1" data-v-3578108a>Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;" data-v-3578108a>​</a></h2><div class="language-bash vp-adaptive-theme" data-v-3578108a><button title="Copy Code" class="copy" data-v-3578108a></button><span class="lang" data-v-3578108a>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-3578108a><code data-v-3578108a><span class="line" data-v-3578108a><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;" data-v-3578108a># place apple-v1.0.0.blueprint in /var/www/pterodactyl, then:</span></span>
<span class="line" data-v-3578108a><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-3578108a>blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-3578108a> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-3578108a> apple-v1.0.0</span></span></code></pre></div><p data-v-3578108a>Open <strong data-v-3578108a>Admin → Apple Theme</strong> — defaults apply on first load, so the admin area looks right before you change a thing. See <a href="./getting-started/installation" data-v-3578108a>Installation</a> for the standalone variant, verification and troubleshooting.</p><hr data-v-3578108a><h2 id="why-apple-instead-of" tabindex="-1" data-v-3578108a>Why Apple instead of… <a class="header-anchor" href="#why-apple-instead-of" aria-label="Permalink to &quot;Why Apple instead of…&quot;" data-v-3578108a>​</a></h2><table tabindex="0" data-v-3578108a><thead data-v-3578108a><tr data-v-3578108a><th data-v-3578108a></th><th style="text-align:center;" data-v-3578108a>Apple</th><th style="text-align:center;" data-v-3578108a>Stock admin</th><th style="text-align:center;" data-v-3578108a>Legacy admin themes</th></tr></thead><tbody data-v-3578108a><tr data-v-3578108a><td data-v-3578108a>Sidebar navigation</td><td style="text-align:center;" data-v-3578108a>✅ floating glass rail + drawer</td><td style="text-align:center;" data-v-3578108a>❌ fixed AdminLTE rail</td><td style="text-align:center;" data-v-3578108a>⚠️ hover-expand hacks</td></tr><tr data-v-3578108a><td data-v-3578108a>Dark <strong data-v-3578108a>and</strong> light modes</td><td style="text-align:center;" data-v-3578108a>✅ Catppuccin Mocha + Latte, instant toggle</td><td style="text-align:center;" data-v-3578108a>❌ single skin</td><td style="text-align:center;" data-v-3578108a>⚠️ two diverging CSS forks</td></tr><tr data-v-3578108a><td data-v-3578108a>Other extensions in the sidebar</td><td style="text-align:center;" data-v-3578108a>✅ automatic, runtime-harvested</td><td style="text-align:center;" data-v-3578108a>✅ (stock list)</td><td style="text-align:center;" data-v-3578108a>❌ hardcoded, links vanish</td></tr><tr data-v-3578108a><td data-v-3578108a>Extension pages themed</td><td style="text-align:center;" data-v-3578108a>✅ global component reskin</td><td style="text-align:center;" data-v-3578108a>—</td><td style="text-align:center;" data-v-3578108a>⚠️ per-page rewrites</td></tr><tr data-v-3578108a><td data-v-3578108a>Dashboard</td><td style="text-align:center;" data-v-3578108a>✅ bento grid, live stats, sparkline</td><td style="text-align:center;" data-v-3578108a>❌ one info box</td><td style="text-align:center;" data-v-3578108a>⚠️ raw SQL in the view</td></tr><tr data-v-3578108a><td data-v-3578108a>Core files replaced</td><td style="text-align:center;" data-v-3578108a>✅ none¹</td><td style="text-align:center;" data-v-3578108a>—</td><td style="text-align:center;" data-v-3578108a>❌ layout + views overwritten</td></tr><tr data-v-3578108a><td data-v-3578108a>External assets loaded</td><td style="text-align:center;" data-v-3578108a>✅ none</td><td style="text-align:center;" data-v-3578108a>⚠️ FA/Ionicons CDN</td><td style="text-align:center;" data-v-3578108a>⚠️ fonts/charts CDN</td></tr></tbody></table><p data-v-3578108a>¹ <em data-v-3578108a>The dashboard view is swapped by an idempotent, marker-verified patch with the original backed up next to it and restored on uninstall — it is the one deliberate exception, and it can be switched off from the settings hub without removing the theme.</em></p><blockquote data-v-3578108a><p data-v-3578108a><strong data-v-3578108a>Bottom line:</strong> legacy admin themes overwrite <code data-v-3578108a>layouts/admin.blade.php</code> and hardcode the menu — every other extension&#39;s link silently disappears, and uninstalling wipes the panel. Apple reads the menu the panel already built and styles what extensions already render.</p></blockquote><hr data-v-3578108a><div class="tip custom-block" data-v-3578108a><p class="custom-block-title" data-v-3578108a>VERIFIED LIVE</p><p data-v-3578108a>Every surface was verified on a real Pterodactyl 1.12 panel during development: dashboard, servers, users, settings, nests, extensions and the settings hub in both modes, the mobile drawer at phone width, settings save/reset, and a full uninstall → reinstall cycle — via automated browser screenshots with zero console errors.</p></div><hr data-v-3578108a><h2 id="next-steps" tabindex="-1" data-v-3578108a>Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-3578108a>​</a></h2><ul data-v-3578108a><li data-v-3578108a><strong data-v-3578108a><a href="./getting-started/installation" data-v-3578108a>Installation →</a></strong> — Blueprint and standalone, verify, troubleshoot, uninstall.</li><li data-v-3578108a><strong data-v-3578108a><a href="./configuration/reference" data-v-3578108a>Configuration Reference →</a></strong> — every setting, every default, every token.</li><li data-v-3578108a><strong data-v-3578108a><a href="./user-guide/using-the-theme" data-v-3578108a>Using the Theme →</a></strong> — toggle, rail, filter, drawer, loader.</li><li data-v-3578108a><strong data-v-3578108a><a href="./user-guide/compatibility" data-v-3578108a>Extension Compatibility →</a></strong> — how other extensions adapt automatically.</li></ul><hr data-v-3578108a><div class="footer-note" data-v-3578108a><p data-v-3578108a><strong data-v-3578108a>Developed for <a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-3578108a>PingLess Studios</a></strong></p><p data-v-3578108a>Questions or licensing — reach us at <a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-3578108a>studio.pingless.org</a>.</p></div>`,20))])}const A=d(c,[["render",v],["__scopeId","data-v-3578108a"]]);export{k as __pageData,A as default};
